var n=`0689-groundnut-stew`;var i=`world-0689`;var a=`SL`;var r=`western-africa`;var s=4;var o=69;var g={en:`Groundnut Stew`,ua:`Арахісове рагу`};var l={en:`Groundnut Stew is a Sierra Leone classic prepared with chicken thigh, yellow onion, peanut butter, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Арахісове рагу, страва кухні країни Сьєрра-Леоне зі складниками: куряче стегно, жовта цибуля, арахісова паста, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 11 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 11 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:11,i:[[`chicken-thigh`,660,`g`],[`yellow-onion`,190,`g`],[`red-palm-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 55 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 55 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:55,i:[[`peanut-butter`,210,`g`],[`water`,800,`ml`],[`tomato`,320,`g`],[`okra`,170,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ginger-root`,20,`g`],[`table-salt`,null,`to_taste`]]}];var h={slug:n,id:i,country:`SL`,region:r,servings:4,minutes:69,title:g,text:l,steps:u};export{a as country,h as default,i as id,o as minutes,r as region,s as servings,n as slug,u as steps,l as text,g as title};